namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00012 : ControllerTestBase
    {
        [TestMethod]
        public void Allow_Anonymous_Is_Not_Allowed_To_Place_On_Any_Method()
        {
            var whiteList = new { ControllerName = "Alive", Method = "Alive" };

            var noSecurity = (from controller in Controllers
                              from method in controller.Methods
                              from methodAttribute in method.Attributes
                              where methodAttribute.Name.Contains("AllowAnonymous")
                              select new
                              {
                                  ErrorClass = controller.FullQualifiedName,
                                  Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
MethodName: {method.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:     

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:     

{method.MethodValue.Replace("[AllowAnonymous]", string.Empty).FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                              }).ToImmutableList();


            Assert.IsTrue(noSecurity.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00012

Please never use [AllowAnonymous] attributes on methods. Findings {noSecurity.Count}': {Environment.NewLine}{noSecurity.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
